from itertools import product


def monic(p, k):
    return [list(low) + [1] for low in product(range(p), repeat=k)]


def count_irreducible(p, d):
    """Monic irreducible polynomials of degree d over Z_p."""
    count = 0
    for f in monic(p, d):
        if not any(poly_divmod(f, g, p)[1] == [0]
                   for k in range(1, d // 2 + 1) for g in monic(p, k)):
            count += 1
    return count
